import { Box, Flex, Text } from "@chakra-ui/react";
import { ChevronDown, Icon } from "../../Icon";
import type { BlockRuntimeStatus } from "./types";

interface SkillBlockCardProps {
  readonly blockId: string;
  readonly status: BlockRuntimeStatus;
  readonly expanded: boolean;
  readonly onToggle: () => void;
  readonly children?: React.ReactNode;
}

/**
 * Compact ordered-block header in the skill document, mirroring the
 * InlineBlockFlow chrome from the Inspector redesign: a one-line mono header
 * with green active state and a chevron that toggles the inline canvas.
 *
 * The header shows the block id. Ordered blocks have no description.
 */
export function SkillBlockCard({
  blockId,
  status,
  expanded,
  onToggle,
  children,
}: SkillBlockCardProps) {
  const isActive = status === "active";

  let statusLabel: React.ReactNode = null;
  if (isActive) {
    statusLabel = (
      <Text as="span" textStyle="2xs" color="green.fg" flexShrink={0}>
        active
      </Text>
    );
  } else if (status === "completed") {
    statusLabel = (
      <Text as="span" textStyle="2xs" color="fg.subtle" flexShrink={0}>
        completed
      </Text>
    );
  }

  return (
    <Flex
      direction="column"
      flexGrow={expanded ? 1 : 0}
      flexShrink={0}
      borderWidth="1px"
      borderColor={isActive ? "green.emphasized" : "border.emphasized"}
      borderRadius="md"
      overflow="hidden"
      data-testid="skill-block-card"
      data-block-id={blockId}
      data-status={status}
      data-expanded={expanded}
    >
      <Flex
        as="button"
        onClick={onToggle}
        align="center"
        gap="2"
        px="3"
        h="9"
        width="100%"
        borderBottomWidth={expanded ? "1px" : "0"}
        borderColor="border"
        bg={isActive ? "green.subtle" : "bg.muted"}
        cursor="pointer"
        _hover={{ bg: isActive ? "green.subtle" : "bg.subtle" }}
        aria-expanded={expanded}
      >
        <Text
          as="span"
          fontFamily="mono"
          textStyle="2xs"
          color={isActive ? "green.fg" : "fg.muted"}
          truncate
          flex="1"
          textAlign="left"
        >
          ordered_block · {blockId}
        </Text>
        {statusLabel}
        <Box
          color={isActive ? "green.fg" : "fg.subtle"}
          display="inline-flex"
          flexShrink={0}
          transform={expanded ? "rotate(180deg)" : undefined}
          transition="transform 0.15s ease"
        >
          <Icon icon={ChevronDown} size="sm" />
        </Box>
      </Flex>
      {expanded ? children : null}
    </Flex>
  );
}
